roke:#f4d98e;stroke-width:2.8}.country.at-war{fill:#ae6355;stroke:#e49a82}.country.owned{fill:#84a485;stroke:#deca87;stroke-width:3}.small-country{stroke-width:1.2}.map-labels{pointer-events:none;fill:#d7d2c0;font:10px var(--mono);letter-spacing:2px;opacity:.56}.map-labels text:nth-of-type(7){font-size:13px;letter-spacing:5px;opacity:.6}.map-pin{display:none;transform:translate(400px,440px);fill:var(--gold2);stroke:#26372e;stroke-width:2}.map-pin circle:first-child{opacity:.9}.map-legend{position:absolute;left:22px;bottom:15px;display:flex;gap:17px;color:#bdc4b8;font:8px var(--mono);letter-spacing:.5px;background:#142326c9;padding:9px 11px;border:1px solid #40504a}.map-legend span{display:flex;align-items:center;gap:6px}.legend-dot{width:7px;height:7px;border-radius:50%;display:inline-block}.legend-dot.own{background:#d2ae67}.legend-dot.neutral{background:#82977e}.legend-dot.war{background:#c77765}.intel-panel{background:#19262a;border-left:1px solid #344448;display:flex;flex-direction:column;min-height:0}.nation-banner{min-height:94px;padding:17px 17px 14px;display:flex;align-items:center;gap:12px;border-bottom:1px solid #334246}.nation-flag{width:42px;height:42px;display:grid;place-items:center;background:#243338;border:1px solid #42504c;font-size:25px}.nation-banner small{font:8px var(--mono);color:#899995;letter-spacing:1px}.nation-banner h1{font:500 20px var(--display);margin:2px 0 1px;line-height:1.1}.nation-sub{font:9px var(--mono);color:#95a39d}.panel-tabs{height:39px;display:flex;border-bottom:1px solid #344448}.panel-tab{background:transparent;border:0;border-bottom:2px solid transparent;color:#82918d;flex:1;font:9px var(--mono);letter-spacing:1px}.panel-tab.active{color:var(--gold2);border-bottom-color:var(--gold)}.intel-content{padding:10px 17px 16px;overflow:auto;flex:1}.panel-heading{display:flex;align-items:center;justify-content:space-between;color:#91a09a;font:8px var(--mono);letter-spacing:1px;padding:8px 0 7px}.panel-heading span{color:#7d9185;fon