function compactMoney(n){let a=Math.abs(n);if(a>=1000)return `${n<0?'−':''}$${(a/1000).toFixed(a>=10000?1:2)} tri`;if(a>=1)return `${n<0?'−':''}$${a.toFixed(0)} bi`;return `${n<0?'−':''}$${(a*1000).toFixed(0)} mi`}
