function dateText(){const year=2026+Math.floor(state.month/12),m=state.month%12;return {short:`${monthNames[m]} ${year}`,long:`1 ${monthNames[m]} ${year}`,next:`1 ${monthNames[(m+1)%12]}`}}
function makeCards(){const order=['BR','US','MX','AR','CA','CL','CO','PE','VE','UY'];$('#countryCards').innerHTML=order.map(code=>{const c=countries[code];return `<button class="country-card" data-start="${code}"><span class="emoji">${c.flag}</span><span><b>${c.name}</b><small>PIB ${fmtGDP(c.gdp)}</small></span></button>`}).join('');$$('[data-start]').forEach(b=>b.onclick=()=>startCampaign(b.dataset.start))}
function startCampaign(code){state.player={...countries[code],code};state.selected=code;$('#countrySelect').classList.add('hidden');$('#campaignLabel').textContent='MANDATO · 2026';$('#footerFlag').textContent=state.player.flag;$('#footerCountry').textContent=state.player.name.toUpperCase();selectCountry(code);addEvent(`Mandato iniciado. ${state.player.name} assume o comando.`);updateUI()}
function selectCountry(code){if(!countries[code])return;state.selected=code;$$('.country').forEach(el=>{el.classList.toggle('selected',el.dataset.code===code&&!el.classList.contains('owned'))});const c=code===state.player?.code?state.player:countries[code];$('#flag').textContent=c.flag;$('#nationName').textContent=c.name;$('#nationSub').textContent=code===state.player?.code?'NAÇÃO SOB SEU GOVERNO':`PAÍS INDEPENDENTE · RELAÇÃO ${state.relations[code]??50}`;if(state.player&&code!==state.player.code){$('#selectedActions').classList.add('hidden');$('#relationActions').classList.remove('hidden');$('#relationActions').innerHTML=`<button data-action="trade">Acordo comercial</button><button data-action="aid">Propor cooperação</button><button data-action="war" class="danger">Declarar guerra</button><button data-action="annex" class="danger">Anexar território</button>`;$$('[data-action]').forEach(b=>b.onclick=()=>diplomacy(b.dataset.action,code))}else{$('#selectedActions').classList.remove('hidden');$('#relationActions').classList.add('hidden');$('#selectedActions').textContent=state.player?'Sua nação. Abra Ações para conduzir a política.':'Inicie uma campanha para governar'}if(state.player&&$('#actionsPanel').classList.contains('hidden')===false)$('#nationSub').textContent=code===state.player.code?'NAÇÃO SOB SEU GOVERNO':`PAÍS INDEPENDENTE · RELAÇÃO ${state.relations[code]??50}`}
function updateUI(){if(!state.player)return;const p=state.player;const stability=Math.max(0,Math.min(100,Math.round(100-p.inflation*.25-p.unemployment*.75-p.debt*.075+p.approval*.18)));p.stability=stability;$('#topTreasury').textContent=compactMoney(p.treasury);$('#topGDP').textContent=fmtGDP(p.gdp);$('#topPop').textContent=`${p.pop.toLocaleString('pt-BR',{maximumFractionDigits:1})} mi`;
$('#topStability').textContent=`${stability}/100`;$('#gdp').textContent=fmtGDP(p.gdp);$('#gdpGrowth').textContent=`${p.growth>=0?'▲ +':'▼ '}${p.growth.toFixed(1)}%`;$('#gdpGrowth').style.color=p.growth>=0?'#9dba8b':'#d68a78';$('#gdpCapita').textContent=`$${Math.round(p.gdp*1e12/(p.pop*1e6)).toLocaleString('pt-BR')}`;$('#inflation').textContent=`${p.inflation.toFixed(1)}%`;$('#unemployment').textContent=`${p.unemployment.toFixed(1)}%`;$('#debt').textContent=`${p.debt.toFixed(0)}% do PIB`;
