```js
function stabilityOf(p){
  const inflationPenalty=Math.max(0,p.inflation)*0.3+Math.max(0,p.inflation-10)*0.35;
  const unemploymentPenalty=Math.max(0,p.unemployment)*0.8;
  const debtPenalty=Math.max(0,p.debt-60)*0.25;
  const growthPenalty=Math.max(0,-p.growth)*2;
  const approvalBonus=(p.approval-50)*0.3;
  return Math.max(0,Math.min(100,Math.round(100-inflationPenalty-unemploymentPenalty-debtPenalty-growthPenalty+approvalBonus)));
}
```

