function diplomacy(action,code){
  if(!state.player||code===state.player.code) return;
  if(state.annexed.has(code)){toast(`${countries[code].name} já faz parte do seu território`);return;}
  const c=countries[code];
  if(action==='trade'){
    if(state.wars.has(code)){toast('Comércio suspenso durante a guerra');return;}
    if(state.deals.has(code)){toast('Já existe um acordo comercial com este país');return;}
    if(!spend(5)) return;
    state.deals.add(code);
    state.relations[code]=Math.min(100,(state.relations[code]??50)+8);
    state.player.gdp*=1.002;
    state.player.growth+=0.05;
    normalizePlayer(state.player);
    addEvent(`Acordo comercial firmado com ${c.name}.`);
    toast('Acordo comercial firmado');
  } else if(action==='aid'){
    if(state.wars.has(code)){toast('Cooperação suspensa durante a guerra');return;}
    if(!spend(8)) return;
    state.relations[code]=Math.min(100,(state.relations[code]??50)+12);
    state.player.approval=Math.min(95,state.player.approval+1);
    addEvent(`Missão de cooperação enviada a ${c.name}.`);
    toast('Cooperação diplomática proposta');
  } else if(action==='war'){
    if(state.wars.has(code)){toast('Já existe um conflito ativo com este país');return;}
    state.wars.add(code);
    state.deals.delete(code);
    state.relations[code]=Math.max(0,(state.relations[code]??50)-55);
    $(`.country[data-code="${code}"]`)?.classList.add('at-war');
    state.player.approval=Math.max(5,state.player.approval-3);
    addEvent(`Estado de guerra declarado contra ${c.name}.`);
    toast(`Guerra declarada: ${c.name}`);
  } else if(action==='annex'){
    if(!state.wars.has(code)){toast('É preciso declarar guerra antes de anexar');return;}
    if(state.player.mil<=c.mil){toast('Poder militar insuficiente para ocupar este país');return;}
    const cost=annexCost(code);
    if(!spend(cost)) return;
    state.annexed.add(code);
    state.wars.delete(code);
    state.deals.delete(code);
    state.player.gdp+=c.gdp*0.8;
    state.player.pop+=c.pop;
    state.player.approval=Math.max(5,state.player.approval-8);
    state.player.debt=Math.max(0,state.player.debt+2);
    const el=$(`.country[data-code="${code}"]`);
    el?.classList.remove('at-war','selected');
    el?.classList.add('owned');
    addEvent(`${c.name} capitulou e foi anexada. A ocupação exige estabilidade.`);
    toast(`${c.name} anexada ao território`);
    updateUI();
    selectCountry(state.player.code);
    return;
  }
  updateUI();
  selectCountry(code);
}
```
