```js
function advanceMonth(){
  if(!state.player) return;
  state.month++;
  const p=state.player;
  const annualNet=(p.growth-3.1)/100;
  const monthlyBalance=p.gdp*1000*annualNet/12;
  const warCount=state.wars.size;
  const warUpkeep=warCount*Math.max(0.05,p.gdp*0.0004);
  const net=monthlyBalance-warUpkeep;
  p.treasury+=net;
  if(warCount){
    p.approval=Math.max(5,p.approval-0.15*warCount);
  }
  p.gdp*=1+p.growth/1200;
  p.growth+=(p.baseGrowth-p.growth)*0.04;
  p.inflation+= (3-p.inflation)*0.03 + (Math.random()-0.5)*0.12;
  p.unemployment+=(p.baseUnemployment-p.unemployment)*0.03 + (Math.random()-0.5)*0.09;
  p.approval=Math.max(5,Math.min(95,p.approval+(Math.random()-0.51)*0.25));
  p.debt=Math.max(0,p.debt+(net<0?Math.abs(net)/(p.gdp*1000)*100:-0.02));
  if(p.treasury<0){p.growth-=.08;p.approval-=.3;}
  normalizePlayer(p);
  const stability=stabilityOf(p);
  if(stability>=70){
    state.stableMonths++;
    if(state.stableMonths>=12 && !state.objectiveDone){
      state.objectiveDone=true;
      addEvent('Objetivo de mandato alcançado: economia estável por 12 meses.');
      toast('Objetivo de estabilização alcançado!');
    }
  } else {
    state.stableMonths=0;
  }
  if(state.month%12===0){
    addEvent(`Relatório anual: PIB ${fmtGDP(p.gdp)}, crescimento de ${p.growth.toFixed(1)}%.`);
  }
  updateUI();
}
```
