const panel = await page.locator('#actionsPanel').boundingBox();
const heading = await page.locator('#diplomacyHeading').boundingBox();
const buttons = await page.locator('#relationActions').boundingBox();
console.log({panel, heading, buttons, scrollTop: await page.locator('#actionsPanel').evaluate(el=>el.scrollTop)});
assert.ok(heading.y >= panel.y - 1 && heading.y < panel.y + panel.height, 'diplomacy heading visible in panel');
assert.ok(buttons.y >= panel.y - 1 && buttons.y + buttons.height <= panel.y + panel.height + 1, 'relation buttons visible');
await page.screenshot({path:'/tmp/opencode/fixed-844-actions-scrolled.png'});
assert.deepEqual(errors, []);
await browser.close();
console.log('SCROLL OK');
EOF

