input.command:
node --input-type=module <<'EOF'
import { createRequire } from 'node:module';
import assert from 'node:assert/strict';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true, executablePath:'/usr/bin/chromium', args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:900}});
const errors=[]; page.on('pageerror', e=>errors.push(e.message));
await page.goto('http://127.0.0.1:3002');
await page.locator('[data-start="BR"]').click();
await page.locator('#pauseBtn').click();
assert.match(await page.locator('.country[data-code="BR"]').getAttribute('class'), /player-country/);
assert.match(await page.locator('.country[data-code="BR"]').getAttribute('class'), /selected/);
await page.locator('.country[data-code="AR"]').click();
assert.match(await page.locator('.country[data-code="BR"]').getAttribute('class'), /player-country/);
assert.doesNotMatch(await page.locator('.country[data-code="BR"]').getAttribute('class'), /selected/);
assert.match(await page.locator('.country[data-code="AR"]').getAttribute('class'), /selected/);
await page.screenshot({path:'/tmp/opencode/final-desktop-foreign.png'});
await page.locator('#homeBtn').click();
await page.locator('[data-start="AR"]').click();
assert.match(await page.locator('.country[data-code="AR"]').getAttribute('class'), /player-country/);
assert.doesNotMatch(await page.locator('.country[data-code="BR"]').getAttribute('class'), /player-country/);
assert.deepEqual(errors, []);
console.log('PLAYER HIGHLIGHT OK');
await browser.close();
EOF

node --input-type=module <<'EOF'
import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true, executablePath:'/usr/bin/chromium', args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:900}});
await page.goto('http://127.0.0.1:3002');
await page.locator('[data-start="BR"]').click();
await page.locator('#pauseBtn').click();
await page.locator('.country[data-code="AR"]').click();
const info = await page.evaluate(()=>{
  const el=document.querySelector('.country[data-code="AR"]');
  const cs=getComputedStyle(el);
  return {cls:el.getAttribute('class'), fill:cs.fill, stroke:cs.stroke, outline:cs.outline, active:document.activeElement===el, activeTag:document.activeElement.tagName, bbox:el.getBBox(), rect:el.getBoundingClientRect().toJSON()};
});
console.log(info);
await page.screenshot({path:'/tmp/opencode/focus-before.png'});
await page.evaluate(()=>{document.querySelector('.country[data-code="AR"]').blur();});
await page.screenshot({path:'/tmp/opencode/focus-after.png'});
await browser.close();
EOF

content.text:
.country{fill:#7d917c;stroke:#253333;stroke-width:2;cursor:pointer;transition:fill .16s,stroke .16s;filter:url(#countryShadow)}
.country:hover{fill:#c4aa71;stroke:#f0d397;stroke-width:2.5}
.country.player-country{fill:#8aa985;stroke:#e2cd8a;stroke-width:2.6}
.country.player-country:hover{fill:#c4aa71;stroke:#f0d397}
.country.selected{fill:#c3a363;stroke:#f4d98e;stroke-width:2.8}
.country.at-war{fill:#ae6355;stroke:#e49a82}
.country.owned{fill:#84a485;stroke:#deca87;stroke-width:3}
.country:focus-visible{outline:none;stroke:#f4d98e;stroke-width:3}
.country-cards{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:11px 0 15px}
.country-card{min-height:78px;background:#233134;border:1px solid #42504b;display:flex;align-items:center;gap:8px;padding:9px;text-align:left;transition:.15s}
.country-card:hover{transform:translateY(-2px);border-color:#d0ad67;background:#2c3834}
.country-card .emoji{font-size:24px}
.country-card b,.country-card small{display:block}
.country-card b{font:500 12px var(--display);color:#e5e4d7}
.country-card small{font:7px var(--mono);color:#97a399;margin-top:4px}
.country-card{padding:6px;gap:5px}
.country-card b{font-size:10px}
.country-card .emoji{font-size:20px}
.country-cards{gap:4px;margin:6px 0 7px}
.country-card{min-height:44px;gap:4px;padding:5px}

