node --check game.js && node --input-type=module <<'EOF'
import { createRequire } from 'node:module';
import assert from 'node:assert/strict';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true, executablePath:'/usr/bin/chromium', args:['--no-sandbox']});
const errors = [];
const page = await browser.newPage({viewport:{width:1440,height:900}});
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://127.0.0.1:3002');

const relation = async () => Number((await page.locator('#nationSub').textContent()).match(/RELAÇÃO (\d+)/)?.[1]);
assert.equal(await page.locator('#countrySelect').isVisible(), true);
assert.equal(await page.locator('#closeSelect').isVisible(), false);
await page.locator('[data-start="BR"]').click();
await page.locator('#pauseBtn').click();
assert.equal(await page.locator('#nationName').textContent(), 'Brasil');
assert.equal(await page.locator('#dateLabel').textContent(), 'JAN 2026');
assert.equal(await page.locator('#topTreasury').textContent(), '$220 bi');
assert.equal(await page.locator('.rail-button.active').getAttribute('data-view'), 'map');
assert.match(await page.locator('.country[data-code="BR"]').getAttribute('class'), /player-country/);
assert.equal(await page.locator('#objectiveProgress').textContent(), '0/12 meses');

// Foreign selection: player remains highlighted, diplomacy opens and scrolls into view
await page.locator('.country[data-code="AR"]').click();
await page.waitForTimeout(250);
assert.equal(await page.locator('#actionsPanel').evaluate(el => el.classList.contains('hidden')), false);
assert.equal(await page.locator('.rail-button.active').getAttribute('data-view'), 'diplomacy');
assert.equal(await page.locator('#relationActions').isVisible(), true);
assert.equal(await page.locator('#relationActions [data-action="war"]').isEnabled(), true);
assert.equal(await page.locator('#relationActions [data-action="annex"]').isEnabled(), false);
assert.match(await page.locator('.country[data-code="BR"]').getAttribute('class'), /player-country/);
assert.doesNotMatch(await page.locator('.country[data-code="BR"]').getAttribute('class'), /selected/);
const focusOutline = await page.locator('.country[data-code="AR"]').evaluate(el => getComputedStyle(el).outlineStyle);
assert.equal(focusOutline, 'none', 'no ugly focus rectangle');
const panelBox = await page.locator('#actionsPanel').boundingBox();
const headingBox = await page.locator('#diplomacyHeading').boundingBox();
assert.ok(headingBox.y >= panelBox.y - 1 && headingBox.y < panelBox.y + panelBox.height, 'diplomacy heading visible');

// Trade, aid, war, peace
const rel0 = await relation();
await page.locator('#relationActions [data-action="trade"]').click();
assert.equal(await page.locator('#topTreasury').textContent(), '$215 bi');
assert.equal(await page.locator('#relationActions [data-action="trade"]').isDisabled(), true);
assert.equal(await relation(), Math.min(100, rel0 + 8));
await page.locator('#relationActions [data-action="aid"]').click();
assert.equal(await page.locator('#topTreasury').textContent(), '$207 bi');
assert.equal(await relation(), Math.min(100, rel0 + 20));
await page.locator('#relationActions [data-action="war"]').click();
assert.match(await page.locator('.country[data-code="AR"]').getAttribute('class'), /at-war/);
assert.equal(await page.locator('#relationActions [data-action="peace"]').isVisible(), true);
await page.locator('#relationActions [data-action="peace"]').click();
assert.doesNotMatch(await page.locator('.country[data-code="AR"]').getAttribute('class'), /at-war/);
assert.match(await page.locator('#nationSub').textContent(), /PAÍS INDEPENDENTE/);

// War and annex
await page.locator('#relationActions [data-action="war"]').click();
assert.equal(await page.locator('#relationActions [data-action="annex"]').isEnabled(), true);
await page.locator('#relationActions [data-action="annex"]').click();
assert.match(await page.locator('.country[data-code="AR"]').getAttribute('class'), /owned/);
assert.equal(await page.locator('#nationName').textContent(), 'Brasil');
assert.equal(await page.locator('#topTreasury').textContent(), '$184 bi');
assert.equal(await page.locator('#topPop').textContent(), '262 mi');
assert.match(await page.locator('#topGDP').textContent(), /^\$2\.84 tri$/);
assert.equal(await page.locator('#overviewPanel').evaluate(el => el.classList.contains('hidden')), false);
assert.equal(await page.locator('.rail-button.active').getAttribute('data-view'), 'map');
assert.match(await page.locator('#events').textContent(), /anexada/);
await page.locator('.country[data-code="AR"]').click();
assert.equal(await page.locator('#nationName').textContent(), 'Brasil');
assert.match(await page.locator('#toast').textContent(), /já foi anexada/);

// Policy cooldown
await page.locator('[data-panel="actions"]').click();
assert.equal(await page.locator('.rail-button.active').getAttribute('data-view'), 'economy');
await page.locator('#stimulus').click();
assert.equal(await page.locator('#topTreasury').textContent(), '$164 bi');
assert.equal(await page.locator('#stimulus').isDisabled(), true);
await page.locator('#advanceBtn').click();
assert.equal(await page.locator('#dateLabel').textContent(), 'FEV 2026');
assert.equal(await page.locator('#stimulus').isDisabled(), false);
assert.equal(await page.locator('#pauseBtn').textContent(), '▶');

// Navigation consistency
await page.locator('.country[data-code="AR"]').click();
assert.equal(await page.locator('#nationName').textContent(), 'Brasil');
await page.locator('.country[data-code="US"]').click();
await page.locator('[data-panel="overview"]').click();
assert.equal(await page.locator('#nationName').textContent(), 'Brasil');
assert.equal(await page.locator('#overviewPanel').evaluate(el => el.classList.contains('hidden')), false);

// Speed actually changes cadence
await page.locator('#pauseBtn').click();
await page.locator('#speedBtn').click();
await page.locator('#speedBtn').click();
assert.equal(await page.locator('#speedBtn').textContent(), '4×');
const monthBefore = await page.locator('#dateLabel').textContent();
await page.waitForTimeout(1750);
assert.notEqual(await page.locator('#dateLabel').textContent(), monthBefore);

// Menu can be dismissed; toast is cleared
await page.locator('#pauseBtn').click();
await page.locator('#homeBtn').click();
assert.equal(await page.locator('#closeSelect').isVisible(), true);
assert.equal(await page.locator('#selectKicker').textContent(), 'NOVA CAMPANHA · 2026');
assert.equal(await page.locator('#toast').isVisible(), false);
await page.keyboard.press('Escape');
assert.equal(await page.locator('#countrySelect').isVisible(), false);

// Restart resets everything
await page.locator('#homeBtn').click();
await page.locator('[data-start="AR"]').click();
assert.equal(await page.locator('#dateLabel').textContent(), 'JAN 2026');
assert.equal(await page.locator('#topTreasury').textContent(), '−$18 bi');
assert.equal(await page.locator('.country.owned').count(), 0);
assert.equal(await page.locator('.country.at-war').count(), 0);
assert.equal(await page.locator('#objectiveProgress').textContent(), '0/12 meses');
assert.equal(await page.locator('#speedBtn').textContent(), '1×');
assert.equal(await page.locator('#pauseBtn').textContent(), 'Ⅱ');
assert.equal(await page.locator('.rail-button.active').getAttribute('data-view'), 'map');
assert.equal(await page.locator('#events .event').count(), 1);
assert.match(await page.locator('#events').textContent(), /Mandato iniciado/);
assert.equal(await page.locator('#statusLabel').textContent(), 'EM CRISE');
assert.match(await page.locator('.country[data-code="AR"]').getAttribute('class'), /player-country/);
assert.doesNotMatch(await page.locator('.country[data-code="BR"]').getAttribute('class'), /player-country/);

// Objective completes after 12 stable months
await page.locator('#homeBtn').click();
await page.locator('[data-start="BR"]').click();
await page.locator('#pauseBtn').click();
for (let i = 0; i < 12; i++) await page.locator('#advanceBtn').click();
assert.equal(await page.locator('#dateLabel').textContent(), 'JAN 2027');
assert.equal(await page.locator('#campaignLabel').textContent(), 'MANDATO · 2027');
assert.equal(await page.locator('#objectiveProgress').textContent(), 'CONCLUÍDO');
assert.match(await page.locator('#events').textContent(), /Objetivo de mandato alcançado/);

// Help + Escape
await page.locator('#helpBtn').click();
