import { createRequire } from 'node:module';
import assert from 'node:assert/strict';

const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const base = process.env.BASE || 'http://127.0.0.1:3002';
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
const errors = [];

function watch(page, label) {
  page.on('pageerror', error => errors.push(`${label}: ${error.message}`));
}

async function relation(page) {
  const text = await page.locator('#nationSub').textContent();
  const match = text.match(/RELAÇÃO (\d+)/);
  return match ? Number(match[1]) : null;
}

async function start(page, code) {
  await page.goto(base, { waitUntil: 'load' });
  await page.locator('[data-start="' + code + '"]').click();
  await page.locator('#pauseBtn').click();
  await page.waitForFunction(expected => document.querySelector('#nationName').textContent === expected, code === 'BR' ? 'Brasil' : 'Argentina');
}

// ---------------------------------------------------------------- desktop
{
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  watch(page, 'desktop');
  await page.goto(base, { waitUntil: 'load' });
  assert.equal(await page.locator('#countryCards .country-card').count(), 10);
  assert.equal(await page.locator('#countrySelect').isVisible(), true);
  assert.equal(await page.locator('#closeSelect').isVisible(), false);
  await page.locator('[data-start="BR"]').click();
  await page.locator('#pauseBtn').click();
  await page.waitForFunction(() => document.querySelector('#nationName').textContent === 'Brasil');

  assert.equal(await page.locator('#dateLabel').textContent(), 'JAN 2026');
  assert.equal(await page.locator('#campaignLabel').textContent(), 'MANDATO · 2026');
  assert.equal(await page.locator('#topTreasury').textContent(), '$220 bi');
  assert.equal(await page.locator('#objectiveProgress').textContent(), '0/12 meses');
  assert.equal(await page.locator('.rail-button.active').getAttribute('data-view'), 'map');
  assert.match(await page.locator('.country[data-code="BR"]').getAttribute('class'), /player-country/);
  assert.match(await page.locator('.country[data-code="BR"]').getAttribute('class'), /selected/);
  const playerFill = await page.locator('.country[data-code="BR"]').evaluate(el => getComputedStyle(el).fill);
  assert.equal(playerFill, 'rgb(138, 169, 133)', 'player keeps its green identity while selected');

  await page.locator('.country[data-code="AR"]').click();
  await page.waitForTimeout(250);
  assert.equal(await page.locator('#actionsPanel').evaluate(el => el.classList.contains('hidden')), false);
  assert.equal(await page.locator('.rail-button.active').getAttribute('data-view'), 'diplomacy');
  assert.equal(await page.locator('#relationActions').isVisible(), true);
  assert.equal(await page.locator('#relationActions [data-action="war"]').isEnabled(), true);
  assert.equal(await page.locator('#relationActions [data-action="annex"]').isEnabled(), false);
  assert.match(await page.locator('.country[data-code="BR"]').getAttribute('class'), /player-country/);
  assert.doesNotMatch(await page.locator('.country[data-code="BR"]').getAttribute('class'), /selected/);
  assert.equal(await page.locator('.country[data-code="AR"]').evaluate(el => getComputedStyle(el).outlineStyle), 'none');
  const panelBox = await page.locator('#actionsPanel').boundingBox();
  const headingBox = await page.locator('#diplomacyHeading').boundingBox();
  assert.ok(headingBox.y >= panelBox.y - 1 && headingBox.y < panelBox.y + panelBox.height, 'diplomacy heading visible');

  const rel0 = await relation(page);
  await page.locator('#relationActions [data-action="trade"]').click();
  assert.equal(await page.locator('#topTreasury').textContent(), '$215 bi');
  assert.equal(await page.locator('#relationActions [data-action="trade"]').isDisabled(), true);
  assert.equal(await relation(page), Math.min(100, rel0 + 8));
  await page.locator('#relationActions [data-action="aid"]').click();
  assert.equal(await page.locator('#topTreasury').textContent(), '$207 bi');
  assert.equal(await relation(page), Math.min(100, rel0 + 20));

  await page.locator('#relationActions [data-action="war"]').click();
  assert.match(await page.locator('.country[data-code="AR"]').getAttribute('class'), /at-war/);
  assert.equal(await page.locator('#relationActions [data-action="peace"]').isVisible(), true);
  assert.equal(await page.locator('#relationActions [data-action="war"]').count(), 0);
  assert.equal(await page.locator('#relationActions [data-action="annex"]').isEnabled(), true);
  const relWar = await relation(page);
  await page.locator('#relationActions [data-action="peace"]').click();
  assert.doesNotMatch(await page.locator('.country[data-code="AR"]').getAttribute('class'), /at-war/);
  assert.match(await page.locator('#nationSub').textContent(), /PAÍS INDEPENDENTE/);
  assert.equal(await relation(page), Math.min(100, relWar + 15));
  assert.match(await page.locator('#toast').textContent(), /Paz firmada/);

  await page.locator('#relationActions [data-action="war"]').click();
  await page.locator('#relationActions [data-action="annex"]').click();
  assert.match(await page.locator('.country[data-code="AR"]').getAttribute('class'), /owned/);
  assert.equal(await page.locator('#nationName').textContent(), 'Brasil');
  assert.equal(await page.locator('#topTreasury').textContent(), '$184 bi');
  assert.equal(await page.locator('#topPop').textContent(), '262 mi');
  assert.match(await page.locator('#topGDP').textContent(), /^\$2\.84 tri$/);
  assert.equal(await page.locator('#overviewPanel').evaluate(el => el.classList.contains('hidden')), false);
  assert.equal(await page.locator('.rail-button.active').getAttribute('data-view'), 'map');
  assert.match(await page.locator('#events').textContent(), /anexada/);

  await page.locator('.country[data-code="AR"]').click();
  assert.equal(await page.locator('#nationName').textContent(), 'Brasil');
  assert.match(await page.locator('#toast').textContent(), /já foi anexada/);

  await page.locator('[data-panel="actions"]').click();
  assert.equal(await page.locator('.rail-button.active').getAttribute('data-view'), 'economy');
  await page.locator('#stimulus').click();
  assert.equal(await page.locator('#topTreasury').textContent(), '$164 bi');
  assert.equal(await page.locator('#stimulus').isDisabled(), true);
  await page.locator('#advanceBtn').click();
  assert.equal(await page.locator('#dateLabel').textContent(), 'FEV 2026');
  assert.equal(await page.locator('#stimulus').isDisabled(), false);
  assert.equal(await page.locator('#pauseBtn').textContent(), '▶');

  await page.locator('.country[data-code="US"]').click();
  await page.locator('.rail-button[data-view="military"]').click();
  await page.waitForTimeout(150);
  assert.equal(await page.locator('#relationActions').isVisible(), true);
  assert.equal(await page.locator('#relationActions [data-action="annex"]').isDisabled(), true);
  assert.match(await page.locator('#relationActions [data-action="annex"]').textContent(), /poder militar insuficiente/);
  const milHeading = await page.locator('#diplomacyHeading').boundingBox();
  const milPanel = await page.locator('#actionsPanel').boundingBox();
  assert.ok(milHeading.y >= milPanel.y - 1 && milHeading.y < milPanel.y + milPanel.height, 'military rail reveals diplomacy');

  await page.locator('.rail-button[data-view="diplomacy"]').click();
  await page.waitForTimeout(150);
  assert.equal(await page.locator('#relationActions').isVisible(), true);

  await page.locator('[data-panel="overview"]').click();
  assert.equal(await page.locator('#nationName').textContent(), 'Brasil');
  assert.equal(await page.locator('#overviewPanel').evaluate(el => el.classList.contains('hidden')), false);

  await page.locator('.country[data-code="US"]').click();
  await page.locator('.rail-button[data-view="map"]').click();
  assert.equal(await page.locator('#nationName').textContent(), 'Brasil');
  assert.equal(await page.locator('#overviewPanel').evaluate(el => el.classList.contains('hidden')), false);

  await page.locator('.country[data-code="US"]').click();
  await page.locator('.rail-button[data-view="economy"]').click();
  assert.equal(await page.locator('#nationName').textContent(), 'Brasil');
  assert.equal(await page.locator('#actionsPanel').evaluate(el => el.classList.contains('hidden')), false);
  assert.equal(await page.locator('.rail-button.active').getAttribute('data-view'), 'economy');
  assert.equal(await page.locator('#selectedActions').isVisible(), true);

  await page.locator('#pauseBtn').click();
  await page.locator('#speedBtn').click();
  await page.locator('#speedBtn').click();
  assert.equal(await page.locator('#speedBtn').textContent(), '4×');
  const monthBefore = await page.locator('#dateLabel').textContent();
  await page.waitForTimeout(1750);
  assert.notEqual(await page.locator('#dateLabel').textContent(), monthBefore);
  await page.locator('#pauseBtn').click();

  await page.locator('#homeBtn').click();
  assert.equal(await page.locator('#closeSelect').isVisible(), true);
  assert.equal(await page.locator('#selectKicker').textContent(), 'NOVA CAMPANHA · 2026');
  assert.equal(await page.locator('#toast').isVisible(), false);
  await page.keyboard.press('Escape');
  assert.equal(await page.locator('#countrySelect').isVisible(), false);

  await page.locator('#homeBtn').click();
  await page.locator('[data-start="AR"]').click();
  assert.equal(await page.locator('#dateLabel').textContent(), 'JAN 2026');
  assert.equal(await page.locator('#topTreasury').textContent(), '−$18 bi');
  assert.equal(await page.locator('.country.owned').count(), 0);
  assert.equal(await page.locator('.country.at-war').count(), 0);
  assert.equal(await page.locator('#objectiveProgress').textContent(), '0/12 meses');
  assert.equal(await page.locator('#speedBtn').textContent(), '1×');
  assert.equal(await page.locator('#pauseBtn').textContent(), 'Ⅱ');
  assert.equal(await page.locator('.rail-button.active').getAttribute('data-view'), 'map');
  assert.equal(await page.locator('#events .event').count(), 1);
  assert.match(await page.locator('#events').textContent(), /Mandato iniciado/);
  assert.equal(await page.locator('#statusLabel').textContent(), 'EM CRISE');
  assert.match(await page.locator('.country[data-code="AR"]').getAttribute('class'), /player-country/);
  assert.doesNotMatch(await page.locator('.country[data-code="BR"]').getAttribute('class'), /player-country/);

  await page.locator('#homeBtn').click();
  await page.locator('[data-start="BR"]').click();
  await page.locator('#pauseBtn').click();
  for (let i = 0; i < 12; i++) await page.locator('#advanceBtn').click();
  assert.equal(await page.locator('#dateLabel').textContent(), 'JAN 2027');
  assert.equal(await page.locator('#campaignLabel').textContent(), 'MANDATO · 2027');
  assert.equal(await page.locator('#objectiveProgress').textContent(), 'CONCLUÍDO');
  assert.match(await page.locator('#events').textContent(), /Objetivo de mandato alcançado/);

  await page.locator('#helpBtn').click();
  assert.equal(await page.locator('#helpModal').isVisible(), true);
  await page.keyboard.press('Escape');
  assert.equal(await page.locator('#helpModal').isVisible(), false);

  await page.screenshot({ path: '/tmp/opencode/final-desktop-validated.png' });
  await page.close();
  console.log('DESKTOP OK');
}

// ---------------------------------------------------------------- phone landscape
{
  const page = await browser.newPage({ viewport: { width: 844, height: 390 } });
  watch(page, 'phone');
  await page.goto(base, { waitUntil: 'load' });
  const modal = await page.locator('.start-modal').boundingBox();
  assert.ok(modal.y >= 0 && modal.y + modal.height <= 390, 'start modal fits phone');
  await page.locator('[data-start="BR"]').click();
  await page.locator('#pauseBtn').click();
  const shell = await page.locator('.game-shell').boundingBox();
  const footer = await page.locator('.timeline-bar').boundingBox();
  const map = await page.locator('.map-stage').boundingBox();
  assert.equal(shell.height, 390);
  assert.ok(footer.y + footer.height <= 390);
  assert.ok(map.height > 250);
  await page.screenshot({ path: '/tmp/opencode/final-phone-game.png' });

  await page.locator('.country[data-code="AR"]').click();
  await page.waitForTimeout(200);
  const panel = await page.locator('#actionsPanel').boundingBox();
  const heading = await page.locator('#diplomacyHeading').boundingBox();
  const buttons = await page.locator('#relationActions').boundingBox();
  assert.ok(heading.y >= panel.y - 1 && heading.y < panel.y + panel.height);
  assert.ok(buttons.y >= panel.y - 1 && buttons.y + buttons.height <= panel.y + panel.height + 1);
  await page.screenshot({ path: '/tmp/opencode/final-phone-diplomacy.png' });

  await page.locator('#relationActions [data-action="war"]').click();
  await page.locator('#relationActions [data-action="annex"]').click();
  assert.equal(await page.locator('#overviewPanel').evaluate(el => el.classList.contains('hidden')), false);
  assert.equal(await page.locator('#nationName').textContent(), 'Brasil');
  await page.screenshot({ path: '/tmp/opencode/final-phone-annexed.png' });

  await page.locator('#homeBtn').click();
  assert.equal(await page.locator('#closeSelect').isVisible(), true);
  await page.screenshot({ path: '/tmp/opencode/final-phone-newcampaign.png' });
  await page.locator('#closeSelect').click();
  await page.close();
  console.log('PHONE OK');
}

// ---------------------------------------------------------------- small landscapes
for (const [width, height, label] of [[568, 320, 'small'], [480, 320, 'tiny'], [400, 300, 'micro']]) {
  const page = await browser.newPage({ viewport: { width, height } });
  watch(page, label);
  await page.goto(base, { waitUntil: 'load' });
  const modal = await page.locator('.start-modal').boundingBox();
  assert.ok(modal.x >= 0 && modal.x + modal.width <= width + 1, `${label}: modal horizontal fit`);
  assert.ok(modal.y >= 0 && modal.y + modal.height <= height + 1, `${label}: modal vertical fit`);
  await page.locator('[data-start="BR"]').click();
  await page.locator('#pauseBtn').click();
  const shell = await page.locator('.game-shell').boundingBox();
  const footer = await page.locator('.timeline-bar').boundingBox();
  const map = await page.locator('.map-stage').boundingBox();
  const settings = await page.locator('#settingsBtn').boundingBox();
  const advance = await page.locator('#advanceBtn').boundingBox();
  const overflow = await page.evaluate(() => Math.max(document.documentElement.scrollWidth, document.body.scrollWidth));
  assert.equal(shell.height, height, `${label}: shell height`);
  assert.ok(footer.y + footer.height <= height + 1, `${label}: footer visible`);
  assert.ok(map.width >= 150 && map.height >= 150, `${label}: map usable`);
  assert.ok(settings.x + settings.width <= width + 1, `${label}: settings visible`);
  assert.ok(advance.x + advance.width <= width + 1, `${label}: advance visible`);
  assert.ok(overflow <= width + 1, `${label}: no horizontal overflow (${overflow})`);

  await page.locator('.country[data-code="AR"]').click();
  await page.waitForTimeout(200);
  const panel = await page.locator('#actionsPanel').boundingBox();
  const buttons = await page.locator('#relationActions').boundingBox();
  assert.ok(buttons.y >= panel.y - 1 && buttons.y + buttons.height <= panel.y + panel.height + 1, `${label}: diplomacy buttons visible`);
  await page.locator('#relationActions [data-action="war"]').click();
  await page.locator('#relationActions [data-action="annex"]').click();
  assert.equal(await page.locator('#overviewPanel').evaluate(el => el.classList.contains('hidden')), false, `${label}: annex returns to overview`);
  await page.screenshot({ path: `/tmp/opencode/final-${label}-landscape.png` });
  await page.close();
  console.log(`${label.toUpperCase()} LANDSCAPE OK`);
}

// ---------------------------------------------------------------- portrait guard
{
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  watch(page, 'portrait');
  await page.goto(base, { waitUntil: 'load' });
  assert.equal(await page.locator('.portrait-warning').isVisible(), true);
  assert.equal(await page.locator('.portrait-warning').evaluate(el => getComputedStyle(el).display), 'flex');
  assert.equal(await page.locator('.game-title').evaluate(el => getComputedStyle(el).visibility), 'hidden');
  await page.screenshot({ path: '/tmp/opencode/final-portrait-guard.png' });
  await page.close();
  console.log('PORTRAIT OK');
}

assert.deepEqual(errors, []);
console.log('ALL VALIDATIONS PASSED');
await browser.close();

