const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json','utf8'));
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://127.0.0.1:3000', { waitUntil: 'load' });
await page.waitForFunction(() => document.fonts.status === 'loaded');
const card = page.locator('[data-start="BR"]');
const samples = [];
for (let i=0;i<12;i++) {
  const box = await card.boundingBox();
  const info = await card.evaluate(el => {
    const cs = getComputedStyle(el);
    return { transform: cs.transform, transition: cs.transition, hover: el.matches(':hover'), rect: el.getBoundingClientRect().toJSON() };
  });
  samples.push({i, box, ...info});
  await page.waitForTimeout(100);
}
console.log(JSON.stringify(samples, null, 2));
await page.hover('[data-start="BR"]');
await page.waitForTimeout(300);
console.log('after hover', await card.evaluate(el => ({ transform: getComputedStyle(el).transform, rect: el.getBoundingClientRect().toJSON(), hover: el.matches(':hover') })));
try {
  await card.click({ trial: true, timeout: 5000 });
  console.log('trial click OK');
} catch (e) { console.log('trial click failed', e.message); }
await browser.close();
EOF

