const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const start = Date.now();
await page.goto('http://127.0.0.1:3000', { waitUntil: 'load' });
console.log('load at', Date.now()-start);
for (let i=0;i<25;i++) {
  const data = await page.evaluate(() => ({
    fonts: document.fonts.status,
    card: document.querySelector('[data-start="BR"]').getBoundingClientRect().toJSON(),
    modal: document.querySelector('.start-modal').getBoundingClientRect().toJSON(),
    loaded: [...document.fonts].map(f=>({family:f.family,status:f.status})),
  }));
  console.log(Date.now()-start, data.fonts, 'cardY', data.card.y, 'modalH', data.modal.height, JSON.stringify(data.loaded));
  if (i===0) {
    try { await page.locator('[data-start="BR"]').click({trial:true, timeout:2000}); console.log('immediate trial OK'); }
    catch(e){ console.log('immediate trial FAIL', e.message.split('\n')[0]); }
  }
  await page.waitForTimeout(100);
}
await browser.close();
EOF

