    const cs = getComputedStyle(el);
    return { rect: r.toJSON(), top: top && (top.tagName + '.' + top.className + '#' + top.id), hover: el.matches(':hover'), transform: cs.transform, transition: cs.transition, visibility: cs.visibility, display: cs.display, pointerEvents: cs.pointerEvents };
