input.command:
DISPLAY=:0 node --input-type=module <<'EOF'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json','utf8'));
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
async function fresh() {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://127.0.0.1:3000', { waitUntil: 'load' });
  await page.waitForFunction(() => document.fonts.status === 'loaded');
  return page;
}
async function attempt(name, fn) {
  const page = await fresh();
  try { await fn(page); console.log(name, 'OK', await page.locator('#nationName').textContent()); }
  catch(e){ console.log(name, 'FAIL', e.name, e.message.split('\n')[0]); }
  await page.close();
}
const card = p => p.locator('[data-start="BR"]');
await attempt('A direct click', async p => { await card(p).click({timeout:2000}); });
await attempt('B trial + wait300 + click', async p => { await card(p).click({trial:true,timeout:2000}); await p.waitForTimeout(300); await card(p).click({timeout:2000}); });
await attempt('C trial + click position 10,10', async p => { await card(p).click({trial:true,timeout:2000}); await card(p).click({timeout:2000, position:{x:10,y:10}}); });
await attempt('D trial + mouse.click center', async p => { await card(p).click({trial:true,timeout:2000}); const b=await card(p).boundingBox(); await p.mouse.click(b.x+b.width/2,b.y+b.height/2); });
await attempt('E click child b', async p => { await p.locator('[data-start="BR"] b').click({timeout:2000}); });
await attempt('F trial child b + click child b', async p => { const b=p.locator('[data-start="BR"] b'); await b.click({trial:true,timeout:2000}); await b.click({timeout:2000}); });
await attempt('G trial + wait1000 + click', async p => { await card(p).click({trial:true,timeout:2000}); await p.waitForTimeout(1000); await card(p).click({timeout:2000}); });
await browser.close();
EOF

